#include <stdio.h>
#include <string.h>

#define MAXN 1001

int dp[MAXN][MAXN];

int main(void) {
    char s[MAXN], t[MAXN];
    if (fgets(s, sizeof(s), stdin) == NULL) return 1;
    if (fgets(t, sizeof(t), stdin) == NULL) return 1;
    s[strcspn(s, "\r\n")] = '\0';
    t[strcspn(t, "\r\n")] = '\0';
    int n = (int)strlen(s), m = (int)strlen(t);
    for (int i = 1; i <= n; i++) {
        for (int j = 1; j <= m; j++) {
            if (s[i - 1] == t[j - 1]) dp[i][j] = dp[i - 1][j - 1] + 1;
            else {
                int best = dp[i - 1][j];
                if (dp[i][j - 1] > best) best = dp[i][j - 1];
                dp[i][j] = best;
            }
        }
    }
    printf("%d\n", dp[n][m]);
    return 0;
}

